contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call openMakeFor or openTakeFor depending on a boolean flag.
    // Inputs:
    // - account: the target account for the open call (we must be either the account or multi-invoker, but here msg.sender == address(this) and c was deployed by the checker, so to satisfy onlyAccountOrMultiInvoker we will use account == address(this)).
    // - amount: UFixed18 value to open (represented as uint256 raw units, UFixed18 expects scaled by 1e18 in library functions; however the contract C expects UFixed18 param so passing raw uint maps to UFixed18 via ABI — we just forward the uint).
    // - isMake: whether to call openMakeFor (true) or openTakeFor (false).
    // The rule: after the call (or if it reverts) we assert that the position fee computed locally using visible oracle price and maker/taker fee is non-negative; and if computed fee is zero then the contract's fees for our account did not increase (we observe collateral.fees via controller.collateral().fees but controller() is only accessible via c.controller() public — however c.controller() returns IController; we cannot inspect Collateral fees directly through nested calls. Instead we will rely on the fact that C emits PositionFeeCharged event when it charges a fee — events are not observable in solidity test. So we must instead assert using public functions: c.position(address) and c.pre(address) and that call does not modify balance of this test contract unexpectedly.)

    // Revised simpler rule: calling openMakeFor/openTakeFor never decreases c.latestVersion() (i.e., latestVersion is non-decreasing) and the function either reverts or returns having left latestVersion unchanged or equal — but latestVersion is view of accumulator.latestVersion which only changes on settle; openMakeFor shouldn't change latestVersion. So assert that latestVersion after call equals before call.

    function run(address account, uint256 amount, bool isMake) public payable {
        require(account == address(this)); // ensure onlyAccountOrMultiInvoker passes (msg.sender == account)

        // read before
        uint256 beforeLatest = c.latestVersion();

        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, UFixed18(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterLatest = c.latestVersion();

        // General rule: invoking openMakeFor/openTakeFor does not modify the product-wide latestVersion counter
        assert(afterLatest == beforeLatest);
    }

    // Minimal receive to accept Ether if needed
    receive() external payable {}
}

