    // - amount is the raw uint256 ABI value passed as UFixed18 (no explicit cast is needed in calldata).
    // - isMake selects openMakeFor (true) or openTakeFor (false).
    function run(address account, uint256 amount, bool isMake) public payable {
        // ensure we are authorized as the account (onlyAccountOrMultiInvoker and onlyAccountOwner require msg.sender==account in relevant flows)
        require(account == address(this));

        // observe before-state
        uint256 beforeLatest = c.latestVersion();

        bool reverted;

        // Call the chosen mutating function; record whether it reverted.
        if (isMake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe after-state
        uint256 afterLatest = c.latestVersion();

        // General rule: these position-opening calls must not modify product latestVersion.
        // (They may revert or succeed, but latestVersion must remain equal to before.)
        assert(afterLatest == beforeLatest);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take the account (must be this contract to satisfy onlyAccountOwner) and
    // the raw uint256 amount which we'll pack into UFixed18 by calling UFixed18Lib.from(uint256).
    // However, we cannot refer to library types directly in calldata, so we pass uint256 and
    // rely on the contract's ABI converting the uint256 to the UFixed18 parameter slot when calling.
    // To ensure proper typing at the call site, we cast in-place via the calldata by using
    // an explicit call through low-level ABI encoding.

    function run(address account, uint256 amount, bool isMake) public payable {
        // Must act as the account owner for paths that require onlyAccountOwner
        require(account == address(this));

        // observe before-state via public view
        uint256 beforeLatest = c.latestVersion();

        bool reverted;

        // Perform the call by using try/catch on the typed external function.
        // Convert amount (uint256) to the expected UFixed18 by relying on Solidity's
        // automatic ABI conversion when calling the function with the correct type in source.
        // To do that, we declare a local variable of the expected user-defined type via explicit calldata packing
        // is not possible here, so instead call through try with a bytes-encoded call to ensure correct call.

        if (isMake) {
            // call openMakeFor(address,uint256) where the contract expects UFixed18 for the second arg
            // ABI encoding uses the uint256 slot, so passing amount is valid.
            try c.openMakeFor{value: 0}(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor{value: 0}(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe after-state
        uint256 afterLatest = c.latestVersion();

        // General rule: latestVersion must remain unchanged by these calls
        assert(afterLatest == beforeLatest);
    }

    receive() external payable {}
}

