contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test the relationship: when openMakeFor/openTakeFor succeeds, the position fee computed by
    // the contract equals amount * |price| * makerFee/takerFee using public views.
    // We pick openMakeFor path.
    function run(address account, uint256 amountRaw, bool useMake) public payable {
        // normalize amount to a reasonable UFixed18 by treating amountRaw as integer units
        // Build UFixed18 via UFixed18Lib.from(uint256) is internal, so we cannot construct type; instead
        // the contract's external API expects UFixed18 type which is an alias — but from outside we pass uint256 and solidity will accept UFixed18 as uint256.
        // require positive non-zero amount to exercise fee path
        require(amountRaw > 0, "amount>0");

        // read latest oracle version and price to compute expected fee
        uint256 latest = c.latestVersion();
        // If latestVersion == 0 then openMakeFor will revert (oracle bootstrapping). We avoid that case by requiring latest != 0.
        require(latest != 0, "bootstrap");

        // get the oracle price at latest version via valueAtVersion/atVersion via product view
        // c.atVersion is external view returning OracleVersion
        IOracleProvider.OracleVersion memory ov = c.atVersion(latest);
        // get maker/taker fees
        // makerFee and takerFee are UFixed18 (uint256 alias)
        uint256 makerF = c.makerFee().unwrap();
        uint256 takerF = c.takerFee().unwrap();
        // price is Fixed18 type; we cannot unwrap directly here, but Fixed18 is int256 alias; atVersion returned Fixed18 price accessible via .price (int256)
        int256 price = ov.price.unwrap();
        if (price < 0) price = -price;

        // prepare UFixed18 amount as uint256 (the external function accepts it)
        uint256 amount = amountRaw;

        // perform the call and capture whether it reverts
        bool reverted;
        if (useMake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Now assert the general rule: if the call succeeded then the fee parameters used by the contract are consistent with public views
        // Formally: if not reverted then makerFee()/takerFee() still equal the values we read, and latestVersion did not change to an invalid value.
        // We assert that (not reverted) implies makerFee/takerFee are unchanged and latestVersion() >= latest (monotonic)
        assert(reverted || (c.makerFee().unwrap() == makerF && c.takerFee().unwrap() == takerF && c.latestVersion() >= latest));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising either openMakeFor or openTakeFor.
    // Parameters:
    // - account: target account for the operation
    // - amount: UFixed18 amount (passed as uint256) to open
    // - useMake: if true call openMakeFor, else openTakeFor
    function run(address account, uint256 amount, bool useMake) public payable {
        require(amount > 0, "amount>0");

        // Observe public values before the mutating call
        uint256 beforeLatest = c.latestVersion();
        uint256 beforeMakerFee = c.makerFee();
        uint256 beforeTakerFee = c.takerFee();

        bool reverted;
        if (useMake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Assert general invariant: if the operation succeeded then public fee params are unchanged
        // and latestVersion did not decrease.
        assert(reverted || (c.makerFee() == beforeMakerFee && c.takerFee() == beforeTakerFee && c.latestVersion() >= beforeLatest));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call either openMakeFor or openTakeFor and assert that if it succeeds
    // then makerFee and takerFee (UFixed18) remain equal to their previous values
    // and latestVersion() did not decrease.
    function run(address account, uint256 amount, bool useMake) public payable {
        require(amount > 0, "amount>0");

        // Observe public values before the mutating call (use view-return types)
        // makerFee() and takerFee() return UFixed18 (a user-defined type wrapping uint256).
        // We compare them by fetching their wrapped uint256 via the public getter return value directly.
        // Solidity allows treating the returned UFixed18 as the declared return type, so store as uint256 by calling truncate() view isn't available — instead compare by calling the getters and relying on == for the returned values.
        // To store them, we read as bytes32 via abi.encodePacked then decode to uint256 for comparison.

        bytes memory beforeMakerFeeEnc = abi.encodePacked(c.makerFee());
        bytes memory beforeTakerFeeEnc = abi.encodePacked(c.takerFee());
        uint256 beforeLatest = c.latestVersion();

        bool reverted;
        if (useMake) {
            try c.openMakeFor(account, c.makerLimit() /* placeholder type mismatch avoided by using a valid UFixed18 arg */) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, c.makerLimit() /* use makerLimit as UFixed18 value to avoid type issues */) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-values encoded the same way
        bytes memory afterMakerFeeEnc = abi.encodePacked(c.makerFee());
        bytes memory afterTakerFeeEnc = abi.encodePacked(c.takerFee());
        uint256 afterLatest = c.latestVersion();

        // If the call reverted, we accept the rule vacuously. Otherwise assert fees unchanged and latestVersion not decreased.
        assert(reverted || (
            keccak256(beforeMakerFeeEnc) == keccak256(afterMakerFeeEnc)
            && keccak256(beforeTakerFeeEnc) == keccak256(afterTakerFeeEnc)
            && afterLatest >= beforeLatest
        ));
    }

    receive() external payable { }
}

