contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function with inputs controlling which action and an amount
    // action: 0 = openMakeFor, 1 = openTakeFor
    function run(uint8 action, address account, uint256 rawAmount) public payable {
        require(action <= 1);
        // normalize amount into a UFixed18-like scaled value by using rawAmount (non-zero allowed)
        // We only call view functions before state-changing calls.

        // Read observable before-values
        uint256 beforeLatestVersion = c.latestVersion();
        uint256 beforeLatestVersionAccount = c.latestVersion(account);
        bool beforeClosed = c.closed();

        // Prepare amount as UFixed18 by using UFixed18Lib.ONE = 1e18 scale; but we cannot construct type here.
        // The contract functions expect UFixed18; solidity will allow passing uint256 where the typedef underlying type is uint256.
        uint256 amount = rawAmount;

        // Make the state-changing call and capture whether it reverted
        bool reverted;
        if (action == 0) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read observable after-values
        uint256 afterLatestVersion = c.latestVersion();
        uint256 afterLatestVersionAccount = c.latestVersion(account);
        bool afterClosed = c.closed();

        // General rule asserted:
        // If the call succeeded (not reverted), then:
        //  - the contract must not have become closed by that call (closed remains false), and
        //  - the global latestVersion is >= beforeLatestVersion (monotonic non-decrease), and
        //  - the account's latestVersion is >= beforeLatestVersionAccount (non-decrease).
        // This encodes that successful opens do not revert and do not spontaneously reduce versions or close the product.
        assert(
            reverted || (
                afterClosed == beforeClosed &&
                // monotonicity
                afterLatestVersion >= beforeLatestVersion &&
                afterLatestVersionAccount >= beforeLatestVersionAccount
            )
        );
    }

    receive() external payable {}
}

