contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for property test
    function run(address account, uint256 amount, bool make) public payable {
        require(amount > 0);
        // snapshot pre-state via only public getters
        UFixed18 maintenanceBefore = c.maintenance(account);
        UFixed18 maintenanceNextBefore = c.maintenanceNext(account);
