                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe post-state
        uint256 afterLatest = c.latestVersion();
        C.PrePosition memory preAfter = c.pre(account);

        // General rule to assert:
        // If the call did not revert, then the account's pre position must have advanced (its oracleVersion field equals latestVersion())
        // and either openMake increased pre.openPosition.maker or openTake increased pre.openPosition.taker by at least the provided amount (non-decreasing),
        // and the product charged a non-negative position fee observable by not reverting during collateral settle (we model this by allowing that successful call never makes latestVersion decrease).

        // Formally: if not reverted then afterLatest >= beforeLatest and preAfter.oracleVersion == afterLatest
        // and depending on action, the corresponding openPosition component's unwrap value is >= amount.unwrap() when comparing to previous value.

