contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We observe: when calling openMakeFor or openTakeFor (depending on isMake bool)
    // if the call does not revert, then latestVersion(account) after the call is >= before,
    // and the position fee computed by the product equals non-negative UFixed18 (i.e., not causing negative fee)
    // We cannot directly inspect collateral.settleAccount calls, but collateral.settleAccount would revert on invalid negative
    // so we assert that when the call succeeds, the account's maintenance/position-related getters remain consistent:
    // latestVersion(account) >= previous latestVersion(account) and the account's pre.oracleVersion equals latestVersion()

    // To keep this general, we choose to call either openMakeFor or openTakeFor with arbitrary amount.

    function run(address account, uint256 amount, bool isMake) public payable {
        require(true);

        // Read before-values
        uint256 beforeLatestAccount = c.latestVersion(account);
        uint256 beforeLatest = c.latestVersion();

        bool reverted;
        // perform the action; catch revert
        try c.openMakeFor(account, UFixed18.wrap(amount)) {
            if (!isMake) {
                // we actually wanted openTakeFor; call that separately
                // but calls that change state must be top-level statements; so we only call one of them.
            }
            reverted = false;
        } catch {
            reverted = true;
        }

        // If we chose openMakeFor but intended openTakeFor, run the other branch separately (top-level)
        if (isMake) {
            // already attempted openMakeFor above
        } else {
            bool reverted2;
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            // Combine revert flags: consider overall revert if both attempted calls reverted.
            reverted = reverted && reverted2;
        }

        // Read after-values
        uint256 afterLatestAccount = c.latestVersion(account);
        uint256 afterLatest = c.latestVersion();

        // General rule asserted: if the call(s) did not revert, latestVersion(account) and global latestVersion do not decrease
        assert(reverted || (afterLatestAccount >= beforeLatestAccount && afterLatest >= beforeLatest));
    }

    receive() external payable {}
}

